 s.updateTehranClock=function(){try{let now=new Date(),parts=Object.fromEntries(new Intl.DateTimeFormat('fa-IR-u-ca-persian',{timeZone:'Asia/Tehran',weekday:'long',year:'numeric',month:'long',day:'2-digit'}).formatToParts(now).filter(x=>x.type!=='literal').map(x=>[x.type,x.value])),day=parts.day.length<2?'۰'+parts.day:parts.day;this.tehranDate=`${parts.weekday} / ${day} / ${parts.month} / ${parts.year}`;this.tehranTime=new Intl.DateTimeFormat('fa-IR',{timeZone:'Asia/Tehran',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(now);this.tehranNow=`${this.tehranDate} • ${this.tehranTime}`}catch{this.tehranDate='';this.tehranTime='';this.tehranNow=''}};
