 s.renderReportPng=async function(){let el=document.getElementById('opsReportPaper');if(!el)throw Error('گزارش آماده نیست');if(!window.html2canvas){await new Promise((res,rej)=>{let sc=document.createElement('script');sc.src='/vendor/html2canvas-1.4.1.min.js';sc.onload=res;sc.onerror=rej;document.head.appendChild(sc)})}await document.fonts?.ready;let canvas=await html2canvas(el,{scale:2,backgroundColor:'#fff',useCORS:true,logging:false});return await new Promise(res=>canvas.toBlob(res,'image/png',.95))};
