 s.profileImage=async function(ev,key='photo'){let f=ev.target.files?.[0];if(!f||!f.type.startsWith('image/'))return;let img=new Image(),u=URL.createObjectURL(f);await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=u});let max=key==='photo'?520:900,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);this.adminProfile[key]=c.toDataURL('image/jpeg',.78);URL.revokeObjectURL(u)};
