 s.blobDataUrl=function(blob){return new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)})};
 s.toggleCustomerVoiceNote=async function(){if(this.noteRecording){this.noteRecorder?.requestData?.();this.noteRecorder?.stop();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return this.toast?.('ضبط صدا پشتیبانی نمی‌شود','error');try{let stream=await navigator.mediaDevices.getUserMedia({audio:true}),rec=new MediaRecorder(stream);this.noteChunks=[];this.noteRecorder=rec;rec.ondataavailable=e=>{if(e.data.size)this.noteChunks.push(e.data)};rec.onstop=async()=>{this.noteRecording=false;stream.getTracks().forEach(t=>t.stop());try{let blob=new Blob(this.noteChunks,{type:rec.mimeType||'audio/webm'}),form=new FormData();form.append('audio',blob,'note.webm');let h={'Idempotency-Key':crypto.randomUUID()},csrf=this.cookie('aquagold_csrf');if(csrf)h['X-CSRF-Token']=csrf;let r=await fetch('/api/aqua-ai/transcribe',{method:'POST',body:form,headers:h,credentials:'same-origin'}),d=await r.json();if(!r.ok)throw Error(d.error);await this.addCustomerNote('voice',d.text||'یادداشت صوتی',{audio_data_url:await this.blobDataUrl(blob),audio_mime_type:blob.type})}catch(e){this.toast?.(e.message,'error')}};rec.start(250);this.noteRecording=true;this.toast?.('یادداشت صوتی در حال ضبط است','info')}catch(e){this.toast?.('اجازه میکروفون داده نشد','error')}};
